/*
 * DIS ロードショー Cisco Secure Access デモ用（2026-10-30）
 *
 * 「正規のサイトが改ざんされ、ライブラリに見せかけたスクリプトが埋め込まれた」想定のファイル。
 * ページを開いて約3秒後に、Cisco 公式のフィッシング判定テスト用ドメインへ移動させる。
 * internetbadguys.com は Cisco が提供する無害なテストページで、実際の攻撃コードは含まない。
 *
 * 確認用: URL の末尾に #safe を付けると移動しない（例 https://sample-shoji.tomotomorin.com/#safe）
 */
(function () {
  if (location.hash === '#safe') return;
  var target = 'http://www.internetbadguys.com/';
  setTimeout(function () { location.replace(target); }, 3000);
})();
